    n, m, w = map(int, sys.stdin.readline().split())
    a = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]

    portals = []
    grid = [[float('inf')] * m for _ in range(n)]
    grid[0][0] = 0

    for i in range(n):
        for j in range(m):
            if a[i][j] > 0:
                portals.append((a[i][j], i, j))

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    pq = [(0, 0, 0)]

    while pq:
        dist, x, y = heapq.heappop(pq)
        if dist > grid[x][y]:
            continue
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and a[nx][ny] != -1:
                new_dist = dist + w
                if new_dist < grid[nx][ny]:
                    grid[nx][ny] = new_dist
                    heapq.heappush(pq, (new_dist, nx, ny))

    portal_distances = {p[0]: float('inf') for p in portals}
    portal_positions = {p[0]: (p[1], p[2]) for p in portals}

    for p in portals:
        px, py = p[1], p[2]
        if grid[px][py] < portal_distances[p[0]]:
            portal_distances[p[0]] = grid[px][py]

